def ds(n):return [d for d in range(1,n+1) if n%d==0]
def pf(n):
 a=[];d=2
 while n>1:
  while n%d==0:a.append(d);n//=d
  d+=1
 return a
def lc(a,b):return a*b//gcd(a,b)
def rotate(p,a):
 x,y=p;r=a*pi/180;return [round(x*cos(r)+y*sin(r)),round(-x*sin(r)+y*cos(r))]
def solve(k,a):
 if k=='fixed':return a['value']
 if k=='product':return a['n']*a['k']
 if k in ['quotient','factorPair']:return a['n']//a['d']
 if k=='remainder':return a['n']%a['d']
 if k=='multiples':return [a['n']*i for i in range(a['start'],a['start']+a['count'])]
 if k=='range':return [n for n in range(a['lo'],a['hi']+1) if n%a['n']==0 and (not a.get('odd') or n%2)]
 if k=='divisors':return ds(a['n'])
 if k=='divisorCount':return len(ds(a['n']))
 if k=='selectDivisors':return [d for d in a['options'] if d and a['n']%d==0]
 if k=='selectMultiples':return [n for n in a['options'] if n%a['n']==0]
 if k=='selectCriteria':return [d for d in a['options'] if all(n%d==0 for n in a['ns'])]
 if k=='criteriaTable':return [int(n%d==0) for n in a['ns'] for d in a['ds']]
 if k=='digits':return [d for d in range(10) if all(int(a['pattern'].replace('?',str(d)))%k==0 for k in a['ds'])]
 if k=='sumDigits':return sum(map(int,str(a['n'])))
 if k=='primeSelect':return [n for n in a['options'] if len(ds(n))==2]
 if k=='primeFactors':return pf(a['n'])
 if k=='gcd':return gcd(a['a'],a['b'])
 if k=='lcm':return lc(a['a'],a['b'])
 if k=='commonDivisors':return ds(gcd(a['a'],a['b']))
 if k=='commonMultiples':return [lc(a['a'],a['b'])*i for i in range(1,a['count']+1)]
 if k=='groupsContent':return a['n']//gcd(a['a'],a['b'])
 if k=='cycleCount':return lc(a['a'],a['b'])//a['period']
 if k=='clock':return (a['start']+lc(a['a'],a['b']))%24
 if k=='turn':return (a['start']+a['angle'])%360
 if k=='rotation':return [rotate(p,a['angle']) for p in a['points']]
 if k=='reflection':return [[2*a.get('c',0)-x,y] if a['axis']=='vertical' else [x,2*a.get('c',0)-y] for x,y in a['points']]
 raise ValueError(k)
def nums(a):return ', '.join(map(str,a))
def steps(k,a,v,unit=''):
 if k in ['product','multiples','range','selectMultiples']:
  n=a['n'];calc=f'{n} × {a.get("k",1)} = {n*a.get("k",1)}' if k=='product' else 'Multipliquem '+str(n)+' per enters no negatius i ens quedem amb els que compleixen les condicions.'
  return [f'Busquem múltiples de {n}: totals formats per grups de {n}.',calc,f'Resultat: {nums(v) if isinstance(v,list) else v}.',f'Comprovació: cada total seleccionat es pot dividir entre {n} amb residu 0.']
 if k in ['quotient','remainder','factorPair']:return [f'Dividim {a["n"]} entre {a["d"]}.',f'{a["n"]} = {a["d"]} × {a["n"]//a["d"]} + {a["n"]%a["d"]}.',f'La pregunta demana {"el residu" if k=="remainder" else "el quocient o factor que falta"}: {v}.','Comprovem la igualtat amb la multiplicació i el residu.']
 if k in ['divisors','divisorCount','selectDivisors']:
  n=a['n'];pairs=[f'{d} × {n//d}' for d in ds(n) if d*d<=n]
  return [f'Busquem divisions exactes de {n}, sense dividir mai entre 0.','Parelles de factors: '+'; '.join(pairs)+'.','Tots els divisors positius: '+nums(ds(n))+'.',f'{"Hi ha "+str(v)+" divisors." if k=="divisorCount" else "Resposta demanada: "+(nums(v) if isinstance(v,list) else str(v))+"."} Cada divisor té una parella; no en falta cap.']
 if k=='sumDigits':return [f'Separem totes les xifres de {a["n"]}.',' + '.join(str(a['n']))+' = '+str(v)+'.','Aquest total serveix per comprovar el criteri de 3 o 9.','No ens fixem només en la darrera xifra ni en una part del nombre.']
 if k in ['selectCriteria','criteriaTable','digits']:
  if k=='digits':return [f'Provem les xifres del 0 al 9 al lloc de ? en {a["pattern"]}.',f'El nombre complet ha de ser divisible per {nums(a["ds"])} alhora.',f'Xifres que compleixen totes les divisions exactes: {nums(v)}.','Una xifra només és vàlida si passa cadascuna de les condicions.']
  if k=='selectCriteria':lines=[f'Per {d}: '+', '.join(f'{n} : {d} té residu {n%d}' for n in a['ns'])+'.' for d in a['options']];res='Divisors comuns seleccionats: '+nums(v)+'.'
  else:lines=[f'{n}: '+', '.join(f'per {d}: {"Sí" if n%d==0 else "No"}' for d in a['ds'])+'.' for n in a['ns']];res='Cada casella es comprova amb la divisió corresponent.'
  return ['Apliquem el criteri: última xifra (2/5/10), suma de xifres (3/9) o dues últimes xifres (4).',*lines,res]
 if k=='primeSelect':return ['Un primer té exactament dos divisors positius.',*[f'{n}: divisors {nums(ds(n))} → {"primer" if len(ds(n))==2 else "no primer"}.' for n in a['options']],f'Selecció completa: {nums(v)}. El nombre 1 no és primer ni compost.']
 if k=='primeFactors':return [f'Dividim {a["n"]} successivament per divisors primers.',*[f'{a["n"]//prod(v[:i])} : {d} = {a["n"]//prod(v[:i+1])}' for i,d in enumerate(v)],f'{a["n"]} = '+ ' × '.join(map(str,v))+'. Tots els factors són primers; conservem repeticions.']
 if k in ['gcd','lcm','commonDivisors','commonMultiples','groupsContent','cycleCount','clock']:
  x,y=a['a'],a['b'];g=gcd(x,y);l=lc(x,y)
  factors=f'Per factors: {x} = {" × ".join(map(str,pf(x))) if x>1 else "1"}; {y} = {" × ".join(map(str,pf(y))) if y>1 else "1"}. '
  if k in ['gcd','commonDivisors','groupsContent']:
   return [f'Divisors de {x}: {nums(ds(x))}.',f'Divisors de {y}: {nums(ds(y))}.',f'Comuns: {nums(ds(g))}; el més gran és {g}.',factors+'Prenem només els factors comuns amb la repetició més petita.',f'Comprovació: {x} : {g} = {x//g} i {y} : {g} = {y//g}; no sobra res.',(f'Contingut per paquet: {a["n"]} : {g} = {v}. ' if k=='groupsContent' else '')+f'Resposta demanada: {nums(v) if isinstance(v,list) else v} {unit}.']
  return [f'Busquem el primer múltiple comú positiu de {x} i {y}.',f'{x} × {l//x} = {l}; {y} × {l//y} = {l}. Cap positiu anterior és múltiple de tots dos.',factors+'Prenem tots els factors primers amb la repetició més gran.',f'El m.c.m. és {l}. Comprovem: {l} : {x} = {l//x} i {l} : {y} = {l//y}.',f'Resposta demanada: {nums(v) if isinstance(v,list) else v} {unit}. '+(f'Calen {l} : {a["period"]} = {v} intervals, rondes, torns o capses, segons el context.' if k=='cycleCount' else f'Hora inicial {a["start"]} + {l} hores; en un rellotge de 24 h dona les {v}.' if k=='clock' else '')]
 if k=='turn':return [f'Partim de {a["start"]}° mesurats des del nord en sentit horari.',f'Apliquem {abs(a["angle"])}° en sentit {"horari" if a["angle"]>=0 else "antihorari"}.',f'{a["start"]} + ({a["angle"]}) = {a["start"]+a["angle"]}°. Traiem o afegim voltes de 360°: {v}°.','La fletxa conserva forma i mida; només canvia l’orientació.']
 if k in ['rotation','reflection']:
  desc=f'Gir de {abs(a["angle"])}° {"horari" if a["angle"]>0 else "antihorari"} al voltant de (0; 0).' if k=='rotation' else f'Eix {"vertical" if a["axis"]=="vertical" else "horitzontal"} a {"x" if a["axis"]=="vertical" else "y"} = {a.get("c",0)}.'
  return [desc,*[f'Punt ({p[0]}; {p[1]}) → ({r[0]}; {r[1]}).' for p,r in zip(a['points'],v)],'Comprovem que es conserven les distàncies entre vèrtexs: forma i mida no canvien. '+('Cada punt i el seu reflex són igual de lluny de l’eix.' if k=='reflection' else 'Tots els punts giren el mateix angle i sentit.')]
 return []
def add(topic,fmt,prompt,hint,kind,args,objective,unit=None,options=None,explain=None,source=None,level=2,visual=None):
 world=0 if topic in ['multiples','divisors','criteris','tots-divisors','primers','factors'] else 1 if topic in ['mcm','mcd','metode','coincidencies','repartiments'] else 2
 value=solve(kind,args);q=dict(id=f'mates-{len(B)+1:03}',revision=1,world=world,topic=topic,difficulty=level,source=source or S[topic],objective=objective,essential=True,format=fmt,prompt=prompt,hint=hint,task=dict(kind=kind,args=args),answer=value,steps=explain or steps(kind,args,value,unit or ''),theory=topic)
 if unit:q['unit']=unit
 if options:q['options']=[dict(value=str(i),text=o[0],why=o[1]) for i,o in enumerate(options)]
 if visual:q['visual']=visual
 assert q['steps'],prompt
 B.append(q)
def single(topic,prompt,opts,correct,why,hint,visual=None,source=None):
 add(topic,'single',prompt,hint,'fixed',{'value':str(correct)},'Distingir i justificar: '+prompt,options=[(v,why[i]) for i,v in enumerate(opts)],explain=[why[correct],'Contrasta la condició amb les dades abans de triar.'],visual=visual,source=source,level=1)
